import { type ReactNode } from 'react';

export type FieldProps = {
  label?: string;
  description?: string;
  error?: string;
  required?: boolean;
  disabled?: boolean;
  htmlFor?: string;
  children: ReactNode;
  className?: string;
};

function cn(...classes: (string | false | undefined | null)[]) {
  return classes.filter(Boolean).join(' ');
}

export function Field({
  label,
  description,
  error,
  required = false,
  disabled = false,
  htmlFor,
  children,
  className,
}: FieldProps) {
  return (
    <div
      className={cn('field', disabled && 'field--disabled', className)}
      role="group"
      {...(error ? { 'data-invalid': '' } : {})}
    >
      {label && (
        <label
          className={cn('field__label', required && 'field__label--required')}
          htmlFor={htmlFor}
        >
          {label}
        </label>
      )}
      {children}
      {description && !error && (
        <p className="field__description">{description}</p>
      )}
      {error && (
        <p className="field__error" role="alert">{error}</p>
      )}
    </div>
  );
}

/* -------------------------------------------------------------------------
   Field

   Wrapper for form controls: label + input + description + error.
   Composes with Input, Textarea, Select, Checkbox, etc.
   Colors matched to Figma atom-text-field.

   Orientation: vertical (default)
   ------------------------------------------------------------------------- */

.field {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-1);
  width: 100%;
}

.field__label {
  font-family: var(--font-family-sans), ui-sans-serif, system-ui, sans-serif;
  font-size: var(--font-size-xs);
  font-weight: var(--font-weight-medium);
  line-height: 1;
  color: var(--foreground);
}

.field__label--required::after {
  content: " *";
  color: var(--destructive);
}

.field__description {
  margin-top: var(--spacing-1);
  font-family: var(--font-family-sans), ui-sans-serif, system-ui, sans-serif;
  font-size: var(--font-size-xs);
  line-height: 1.4;
  color: var(--placeholder);
}

.field__error {
  margin-top: var(--spacing-1);
  font-family: var(--font-family-sans), ui-sans-serif, system-ui, sans-serif;
  font-size: var(--font-size-xs);
  line-height: 1.4;
  color: var(--destructive);
}

/* Error state — label turns red */
.field[data-invalid] .field__label {
  color: var(--destructive);
}

/* Disabled state — label grays out */
.field--disabled .field__label {
  color: var(--muted-foreground);
}
